CREATE OR REPLACE FUNCTION private.crm_outbox() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eid uuid:=gen_random_uuid(); et text; tid uuid; body jsonb; BEGIN tid:=NEW.tenant_id; et:=TG_TABLE_NAME||'.'||CASE WHEN TG_OP='INSERT' THEN 'created' ELSE 'updated' END; body:=jsonb_build_object('id',eid,'type',et,'tenant_id',tid,'occurred_at',now(),'data',jsonb_build_object('id',NEW.id,'entity_type',TG_TABLE_NAME,'tenant_id',tid)); INSERT INTO public.crm_deliveries(tenant_id,webhook_id,event_id,event_type,payload) SELECT tid,id,eid,et,body FROM public.crm_webhooks WHERE tenant_id=tid AND enabled AND et=ANY(events); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.crm_claim_deliveries(_tenant uuid DEFAULT NULL) RETURNS SETOF public.crm_deliveries LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 UPDATE public.crm_deliveries SET status='failed',last_error='Delivery lease expired after final attempt',locked_until=NULL WHERE (_tenant IS NULL OR tenant_id=_tenant) AND status='sending' AND locked_until<now() AND attempts>=8;
 RETURN QUERY UPDATE public.crm_deliveries SET status='sending',attempts=attempts+1,locked_until=now()+interval '2 minutes' WHERE id IN (SELECT id FROM public.crm_deliveries WHERE (_tenant IS NULL OR tenant_id=_tenant) AND attempts<8 AND ((status='pending' AND next_attempt_at<=now()) OR (status='sending' AND locked_until<now())) ORDER BY next_attempt_at FOR UPDATE SKIP LOCKED LIMIT 5) RETURNING *; END $$;
CREATE FUNCTION private.crm_link_conversion() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NEW.lead_id IS NOT NULL THEN UPDATE public.enquiries SET contact_id=NEW.contact_id,opportunity_id=NEW.id WHERE tenant_id=NEW.tenant_id AND lead_id=NEW.lead_id AND opportunity_id IS NULL; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION private.crm_link_conversion() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER crm_link_conversion AFTER INSERT ON public.opportunities FOR EACH ROW EXECUTE FUNCTION private.crm_link_conversion();
DROP POLICY enquiry_read ON public.enquiries;
CREATE POLICY enquiry_read ON public.enquiries FOR SELECT TO authenticated USING (tenant_id IN (SELECT private.my_tenants(ARRAY['tenant_admin','sales_manager','ops_coordinator','analyst']::public.app_role[])) OR EXISTS(SELECT 1 FROM public.leads l WHERE l.tenant_id=enquiries.tenant_id AND l.id=enquiries.lead_id AND (l.owner_id=auth.uid() OR l.created_by=auth.uid())));